#!/bin/sh
# Generated by FWShift: rows for the packet filter (and NAT) of a Phoenix Contact mGuard, added with gaiconfig.
# Read the report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE            prints the gaiconfig calls; runs anywhere
#   sh THIS_FILE                      on the mGuard (SSH, as root or admin): adds the groups and rows
#   FWSHIFT_APPEND=yes sh THIS_FILE   also when the tables have rows: the new ones go after them
#
# Nothing is changed or deleted, and no interface, route or access to the mGuard is touched. Every call but the last
# writes with --silent; the last one reconfigures, and the rows take effect then. A call gaiconfig refuses stops the
# script: what was written before is stored but not active (the groups start with 'fws_', the rows' comments
# with the names of the rules); remove it in the web interface, or run the script again after fixing the cause.
set -u
DRY_RUN="${DRY_RUN:-}"
FWSHIFT_APPEND="${FWSHIFT_APPEND:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
gc() {
  if [ -n "$DRY_RUN" ]; then printf 'gaiconfig' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gaiconfig "$@" >/dev/null || fail "gaiconfig $*"
}
rows() {
  if [ -n "$DRY_RUN" ]; then echo 0; return 0; fi
  gaiconfig --get-rowcount "$1" || fail "gaiconfig --get-rowcount $1"
}
named() {
  [ -z "$DRY_RUN" ] && gaiconfig --get "$1" 2>/dev/null | grep -F -q "NAME = \"$2\""
}
if [ -z "$DRY_RUN" ] && ! command -v gaiconfig >/dev/null 2>&1; then fail "gaiconfig not found: run this on the mGuard"; fi
named FW_GROUP_IP fws_Admin-PCs && fail 'an IP group named fws_Admin-PCs exists; nothing was written'
named FW_GROUP_IP fws_Servers && fail 'an IP group named fws_Servers exists; nothing was written'
named FW_GROUP_IP fws_Jump-Hosts__eth1_ && fail 'an IP group named fws_Jump-Hosts__eth1_ exists; nothing was written'
named FW_GROUP_IP fws_Jump-Hosts__eth3_ && fail 'an IP group named fws_Jump-Hosts__eth3_ exists; nothing was written'
named FW_GROUP_PORT fws_Web && fail 'a port group named fws_Web exists; nothing was written'
named FW_GROUP_PORT fws_vpn.ipsec && fail 'a port group named fws_vpn.ipsec exists; nothing was written'

# FW_GROUP_IP
N=$(rows FW_GROUP_IP)
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Admin-PCs --set .COMMENT 'FWShift: Admin-PCs'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.168.10.200-192.168.10.220
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Servers --set .COMMENT 'FWShift: Servers'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 172.16.20.10
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 172.16.20.25
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Jump-Hosts__eth1_ --set .COMMENT 'FWShift: Jump-Hosts (eth1)'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.168.10.5
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Jump-Hosts__eth3_ --set .COMMENT 'FWShift: Jump-Hosts (eth3)'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.30.0.5
N=$((N+1))

# FW_GROUP_PORT
N=$(rows FW_GROUP_PORT)
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_Web --set .COMMENT 'FWShift: Web'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_vpn.ipsec --set .COMMENT 'FWShift: vpn.ipsec'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 500
gc --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 4500
N=$((N+1))

if [ -z "$DRY_RUN" ]; then
  for v in FW_INCOMING_GLOBAL FW_OUTGOING_GLOBAL; do
    g=$(gaiconfig --get "$v" 2>/dev/null || true)
    [ "$g" = rules ] || printf 'NOTE: %s is %s: the rows take effect only with "Use the firewall ruleset below" (rules)\n' "$v" "$g" >&2
  done
fi
echo 'Done. Check the tables in the web interface (Network Security >> Packet Filter, Network >> NAT).' >&2
